MOVED = {'loop': 'agent-core', 'toolexec': 'agent-core', 'providers': 'pi-ai', 'session': 'coding-agent', 'compaction': 'coding-agent',
         'extensions': 'coding-agent', 'modes': 'coding-agent', 'tui': 'tui'}
